<?php
require __DIR__.'/lib.php';require_login();$id=(int)($_POST['id']??$_GET['id']??0);$lock=null;$step='';
try{
 if(!access_page_allowed('warranty_cases'))throw new Exception('Warranty Cases access required.');
 if($_SERVER['REQUEST_METHOD']==='GET'){$r=wc_case($id);if(($_GET['download']??'')==='evidence'){$root=realpath(__DIR__.'/uploads/warranty_cases');$path=realpath(__DIR__.'/'.($r['evidence_path']??''));if(!$root||!$path||!str_starts_with(str_replace('\\','/',$path),str_replace('\\','/',$root).'/')||!is_file($path))throw new Exception('Evidence file unavailable.');header('Content-Type: '.(new finfo(FILEINFO_MIME_TYPE))->file($path));header('Content-Disposition: inline; filename="Warranty_Evidence.'.pathinfo($path,PATHINFO_EXTENSION).'"');header('Cache-Control: private, no-store');readfile($path);exit;}throw new Exception('Unknown download.');}
 if($_SERVER['REQUEST_METHOD']!=='POST')throw new Exception('Use the form.');verify_csrf();$a=$_POST['action']??'';$permission=['wc_receive_preview'=>'wc_receive','wc_release_preview'=>'wc_release'][$a]??$a;if(!in_array($a,['wc_setup','wc_create','wc_decide','wc_receive_preview','wc_receive','wc_release_preview','wc_release','wc_close'],true)||!can_action($permission))throw new Exception('Your role cannot perform this warranty action.');$lock=inventory_write_lock();
 if($a==='wc_setup'){wc_install();flash('Warranty Cases enabled. Assign the CSR role in Users / Settings. No stocks changed.');}
 elseif($a==='wc_create'){$key=$_POST['request_key']??'';if(empty($_SESSION['wc_keys'][$key]))throw new Exception('Reopen the new case form.');$id=wc_create($_POST,$_FILES['evidence']??null);flash('Warranty recorded for Operations Lead review. No stock changed.');}
 elseif($a==='wc_decide'){wc_decide($id,$_POST);unset($_SESSION['wc_preview'][$id]);flash('Decision and approved source saved. No stock changed.');}
 elseif(in_array($a,['wc_receive_preview','wc_release_preview'],true)){$mode=$a==='wc_receive_preview'?'receive':'release';$plan=process_transaction(fn()=> $mode==='receive'?wc_receive_plan($id,$_POST):wc_release_plan($id));$_SESSION['wc_preview'][$id]=['mode'=>$mode,'plan'=>$plan,'input'=>$mode==='receive'?['txn_date'=>$_POST['txn_date'],'receipt_ref'=>$_POST['receipt_ref'],'linked_return_id'=>$_POST['linked_return_id']??'']:[],'uid'=>current_user()['id'],'token'=>bin2hex(random_bytes(24))];$step='&step=review';}
 elseif(in_array($a,['wc_receive','wc_release'],true)){$saved=$_SESSION['wc_preview'][$id]??null;$mode=$a==='wc_receive'?'receive':'release';if(!$saved||$saved['mode']!==$mode||$saved['uid']!==current_user()['id']||!hash_equals($saved['token'],(string)($_POST['token']??'')))throw new Exception('Review the current stock / custody effects first.');if($mode==='receive')wc_receive($id,$saved['input'],$saved['plan']['digest'],!empty($_POST['physical_ack']));else wc_release($id,$saved['plan']['digest'],$_POST['replacement_ref']??'',$_POST['inspection']??'',!empty($_POST['physical_ack']));unset($_SESSION['wc_preview'][$id]);flash($mode==='receive'?'Receiving recorded once. Review the replacement before physical release.':'Warranty release recorded once, including donor / stock history.');}
 elseif($a==='wc_close'){wc_close($id,$_POST);flash('Warranty case closed; all evidence and movements retained.');}
}catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();flash(safe_error_message($ex),'danger');if($_SERVER['REQUEST_METHOD']==='GET'){http_response_code(400);exit('Download unavailable.');}}finally{if($lock)inventory_write_unlock($lock);}header('Location: index.php?page=warranty_cases'.($id?'&id='.$id:'').$step);exit;
